/**
 * @summary Send log lines (ingest token)
 */

export function useIngestLogs<TData = Awaited<ReturnType<typeof ingestLogs>>, TError = ErrorResponse>(
 ingestLogsBody: string, options?: { query?:Partial<UseQueryOptions<Awaited<ReturnType<typeof ingestLogs>>, TError, TData>>, request?: SecondParameter<typeof customFetch>}
 , queryClient?: QueryClient
 ):  UseQueryResult<TData, TError> & { queryKey: DataTag<QueryKey, TData, TError> } {

  const queryOptions = getIngestLogsQueryOptions(ingestLogsBody,options)

  const query = useQuery(queryOptions, queryClient) as  UseQueryResult<TData, TError> & { queryKey: DataTag<QueryKey, TData, TError> };

  return withQueryKey(query, queryOptions.queryKey);
}






